mapper.select:
SELECT dept_name AS deptName, -- 科室名称 NVL(SUM(remain_alert), 0) AS remainAlert, -- 滞留预警 NVL(SUM(appointment_alert), 0) AS appointmentAlert, -- 预约预警 NVL(SUM(early_leave), 0) AS earlyLeave -- 早退人数 FROM TR_OUTP_ALT_OV WHERE stat_date BETWEEN #{startDate} AND #{endDate}
AND dept_code = #{deptCode}
AND dept_name LIKE '%' || #{deptName} || '%'
GROUP BY dept_name ORDER BY remainAlert DESC
